solution.javascript:
function inventaire(coffre, profondeur = 1) {
  const resultat = [];
  for (const element of coffre) {
    if (Array.isArray(element)) {
      const dedans = inventaire(element, profondeur + 1);
      for (const paire of dedans) {
        resultat.push(paire);
      }
    } else {
      resultat.push([element, profondeur]);
    }
  }
  return resultat;
}

solution.python:
def inventaire(coffre, profondeur=1):
    resultat = []
    for element in coffre:
        if isinstance(element, list):
            dedans = inventaire(element, profondeur + 1)
            for paire in dedans:
                resultat.append(paire)
        else:
            resultat.append([element, profondeur])
    return resultat

