function parcourir(elements, cles, cadeaux) {
  for (const element of elements) {
    if (typeof element === "string") {
      if (cadeaux !== null) {
        cadeaux.push(element);
      }
    } else if ("cle" in element) {
      cles.add(element.cle);
    } else if (element.serrure === null || cles.has(element.serrure)) {
      parcourir(element.contenu, cles, cadeaux);
    }
  }
}

function ouvrirCoffres(elements) {
  const cles = new Set();
  let change = true;
  while (change) {
    const avant = cles.size;
    parcourir(elements, cles, null);
    change = cles.size > avant;
  }
  const cadeaux = [];
  parcourir(elements, cles, cadeaux);
  return cadeaux;
}

